const inventory=new InventoryIndex(norm,ident);let entryLimit=30,searchFrame=0,reloading=null,previewSequence=0;
let excelWorker=null,workerId=0,workerPromise=null,workerGeneration=0,excelWorkerURL=null;const workerJobs=new Map();
function stopWorker(message='پردازش فایل متوقف شد.'){workerGeneration++;if(excelWorker)excelWorker.terminate();excelWorker=null;workerPromise=null;if(excelWorkerURL)URL.revokeObjectURL(excelWorkerURL);excelWorkerURL=null;for(const job of workerJobs.values()){clearTimeout(job.timer);job.reject(Error(message));}workerJobs.clear();}
async function getExcelWorker(){if(excelWorker)return excelWorker;if(workerPromise)return workerPromise;const generation=workerGeneration;workerPromise=(async()=>{const blob=await window.loadOfflineExcelBundle();if(generation!==workerGeneration)throw Error('پردازش فایل لغو شد.');excelWorkerURL=URL.createObjectURL(blob);const worker=new Worker(excelWorkerURL);excelWorker=worker;worker.onmessage=({data:m})=>{const job=workerJobs.get(m.id);if(!job)return;clearTimeout(job.timer);workerJobs.delete(m.id);m.error?job.reject(Error(m.error)):job.resolve(m.result);};worker.onerror=()=>stopWorker('بخش خواندن اکسل اجرا نشد؛ برنامه را یک بار با اینترنت از آیکون صفحهٔ اصلی باز کنید و منتظر آمادهٔ کار آفلاین بمانید.');worker.onmessageerror=()=>stopWorker('پاسخ پردازش فایل کامل دریافت نشد.');return worker;})();try{return await workerPromise;}catch(e){if(generation===workerGeneration)stopWorker(e.message);throw e;}}
async function workerTask(type,data,transfer=[]){const worker=await getExcelWorker();return new Promise((resolve,reject)=>{const id=++workerId,timer=setTimeout(()=>stopWorker('پردازش فایل بیش از حد طول کشید؛ دوباره تلاش کنید.'),120000);workerJobs.set(id,{resolve,reject,timer});try{worker.postMessage({id,type,data},transfer);}catch(e){clearTimeout(timer);workerJobs.delete(id);reject(e);}});}
function rawInfo(value){if(!value)return null;const {bytes,...info}=value;return info;}
function bulkAdd(store,rows,done){let i=0;function chunk(){let last;const end=Math.min(i+200,rows.length);for(;i<end;i++)last=store.add(rows[i]);if(i<rows.length)last.onsuccess=chunk;else if(done)done();}chunk();}
function uid(){if(crypto.randomUUID)return crypto.randomUUID();return Array.from(crypto.getRandomValues(new Uint8Array(24)),n=>n.toString(16).padStart(2,'0')).join('');}
function notify(msg,error=false){$('toast').textContent=msg;$('toast').className=error?'error-toast':'';$('toast').hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').hidden=true,7000);}
function fail(message){$('fatal').hidden=false;$('fatal').innerHTML=`<h2>برنامه آماده نشد</h2><p>${esc(message)}</p><p>داده‌های برنامه را پاک نکنید؛ برنامه را ببندید و دوباره باز کنید.</p>`;}
function parseQty(value){const s=en(value).replace(/٫/g,'.').replace(/٬/g,'').trim();if(!/^\d+(?:\.\d{1,3})?$/.test(s))throw Error('عدد صفر یا بیشتر، با حداکثر سه رقم اعشار وارد کنید.');const [a,b='']=s.split('.');const n=Number(a)*1000+Number(b.padEnd(3,'0'));if(!Number.isSafeInteger(n)||n>MAX_QTY)throw Error('تعداد از محدوده مجاز بیشتر است.');return n;}
function openDB(){return new Promise((resolve,reject)=>{const r=indexedDB.open(DB_NAME,2);r.onupgradeneeded=()=>{const d=r.result;for(const name of ['meta','products','entries'])if(!d.objectStoreNames.contains(name))d.createObjectStore(name,{keyPath:name==='meta'?'key':'id'});const es=r.transaction.objectStore('entries'),ps=r.transaction.objectStore('products');if(!es.indexNames.contains('productRound'))es.createIndex('productRound',['productId','round']);if(!ps.indexNames.contains('key'))ps.createIndex('key','key');};r.onsuccess=()=>{r.result.onversionchange=()=>r.result.close();resolve(r.result);};r.onerror=()=>reject(r.error||Error('پایگاه داده گوشی باز نشد.'));r.onblocked=()=>reject(Error('نسخه دیگری از برنامه باز است. ابتدا آن را ببندید.'));});}
function write(stores,enqueue){return new Promise((resolve,reject)=>{let tx,result,problem;try{try{tx=db.transaction(stores,'readwrite',{durability:'strict'});}catch{tx=db.transaction(stores,'readwrite');}const done=x=>result=x;const stop=e=>{problem=e;tx.abort();};enqueue(tx,done,stop);tx.oncomplete=()=>resolve(result);tx.onabort=()=>reject(problem||tx.error||Error('ذخیره انجام نشد؛ حافظهٔ گوشی را بررسی کنید.'));tx.onerror=()=>{};}catch(e){if(tx)try{tx.abort();}catch{}reject(e);}});}
function snapshot(){return new Promise((resolve,reject)=>{const tx=db.transaction(['meta','products','entries'],'readonly'),m=tx.objectStore('meta'),out={};m.get('settings').onsuccess=e=>out.settings=e.target.result?.value||settings;m.get('raw').onsuccess=e=>out.raw=e.target.result?.value||null;tx.objectStore('products').getAll().onsuccess=e=>out.products=e.target.result;tx.objectStore('entries').getAll().onsuccess=e=>out.entries=e.target.result;tx.oncomplete=()=>resolve(out);tx.onabort=()=>reject(tx.error||Error('خواندن اطلاعات کامل نشد.'));});}
async function reload(){if(reloading)return reloading;reloading=new Promise((resolve,reject)=>{const tx=db.transaction(['meta','products','entries'],'readonly'),m=tx.objectStore('meta'),out={};m.get('settings').onsuccess=e=>out.settings=e.target.result?.value||settings;m.get('rawInfo').onsuccess=e=>{if(e.target.result)out.raw=e.target.result.value;else m.get('raw').onsuccess=e=>out.raw=rawInfo(e.target.result?.value);};tx.objectStore('products').getAll().onsuccess=e=>out.products=e.target.result;tx.objectStore('entries').getAll().onsuccess=e=>out.entries=e.target.result;tx.oncomplete=()=>resolve(out);tx.onabort=()=>reject(tx.error||Error('خواندن اطلاعات کامل نشد.'));});try{const state=await reloading;({products,entries,settings,raw}=state);inventory.rebuild(products,entries);if(raw)await write(['meta'],tx=>tx.objectStore('meta').put({key:'rawInfo',value:raw}));render();}finally{reloading=null;}}
function totalFor(id,round=currentRound,list){if(list)return list.reduce((sum,e)=>sum+(e.productId===id&&e.round===round?e.qtyMilli:0),0)|| (list.some(e=>e.productId===id&&e.round===round)?0:null);return inventory.total(id,round);}
function render(){
 $('context').textContent=settings.warehouse?`${COMPANY[settings.companyId]} · ${settings.warehouse}${settings.period?' · '+settings.period:''}`:'ابتدا مشخصات شمارش را در تنظیمات ثبت کنید.';
 $('productCount').textContent=fmt(products.length);$('entryCount').textContent=fmt(inventory.roundCounts[currentRound]||0);
 $('fileStatus').textContent=raw?`فایل واردشده: ${raw.fileName} · ${fmt(products.filter(p=>p.sourceRow).length)} ردیف خام`:'هنوز فایل خامی وارد نشده است.';
 renderSearch();const recent=inventory.recent(settings.operator,currentRound);
 $('recent').innerHTML=recent.map(e=>{const p=inventory.products.get(e.productId);return p?`<div class="recent-item"><div><h3>${esc(p.name)}</h3><div class="meta">${esc(e.operator)} · ${dateText(e.createdAt)}</div></div><button data-pick="${esc(p.id)}" class="badge">${fmt(e.qtyMilli/1000)}</button></div>`:'';}).join('')||'<p class="empty">در این نوبت هنوز کالایی ثبت نکرده‌اید.</p>';
}
function showTab(tab){activeTab=tab;for(const s of document.querySelectorAll('section[id^="tab-"]'))s.hidden=s.id!==`tab-${tab}`;for(const b of document.querySelectorAll('[data-tab]'))b.classList.toggle('active',b.dataset.tab===tab);if(tab==='settings'){for(const [id,value]of Object.entries({company:settings.companyId,warehouse:settings.warehouse,period:settings.period,operator:settings.operator}))$(id).value=value;for(const id of ['company','warehouse','period'])$(id).disabled=products.length>0;}if(tab==='count')$('search').focus();}
async function saveSettings(){const next={companyId:Number($('company').value),warehouse:$('warehouse').value.trim(),period:$('period').value.trim(),operator:$('operator').value.trim()};if(!COMPANY[next.companyId]||!next.warehouse||!next.operator)throw Error('شرکت، نام انبار و نام شمارشگر را وارد کنید.');if(products.length&&(next.companyId!==settings.companyId||next.warehouse!==settings.warehouse||next.period!==settings.period))throw Error('شرکت و انبار پس از ورود کالا قابل تغییر نیستند.');await write(['meta'],tx=>tx.objectStore('meta').put({key:'settings',value:next}));settings=next;render();showTab('count');notify('مشخصات ذخیره شد.');}
function matches(p,query,mode){if(mode==='tag')return ident(p.tag)!==''&&ident(p.tag)===ident(query);if(mode==='code')return norm(p.code).includes(norm(query));return norm(p.name).includes(norm(query));}
function productHTML(p){const t=totalFor(p.id);return `<div class="product"><div><h3>${esc(p.name)}</h3><div class="meta">${p.tag?`<span>تگ: <code>${esc(p.tag)}</code></span>`:''}${p.code?`<span>کد: <code>${esc(p.code)}</code></span>`:''}</div><span class="badge ${t===null?'unset':''}">${t===null?'شمارش نشده':fmt(t/1000)}</span></div><button class="primary" data-pick="${esc(p.id)}">شمارش</button></div>`;}
function renderSearch(){const q=$('search').value.trim();if(!q){$('results').innerHTML='<p class="empty">برای دیدن کالا، تگ، کد یا نام آن را جست‌وجو کنید.</p>';return;}const all=inventory.search(q,$('searchMode').value,41);$('results').innerHTML=all.slice(0,40).map(productHTML).join('')||'<p class="empty">کالایی پیدا نشد.</p>';if(all.length>40)$('results').insertAdjacentHTML('beforeend','<p class="help">۴۰ نتیجهٔ اول نمایش داده شد؛ عبارت دقیق‌تری وارد کنید.</p>');}
function scheduleSearch(){cancelAnimationFrame(searchFrame);searchFrame=requestAnimationFrame(renderSearch);}
function modal(title,body){$('modalTitle').textContent=title;$('modalBody').innerHTML=body;if(!$('modal').open)$('modal').showModal();}
function closeModal(){if(saving)return;$('modal').close();selected=null;if(staged){staged=null;stopWorker();}}
function showCount(id){const p=inventory.products.get(id);if(!p)return;selected=id;entryLimit=30;const t=totalFor(id);modal('ثبت شمارش',`<h3>${esc(p.name)}</h3><div class="meta"><span>کد: <code>${esc(p.code||'—')}</code></span><span>تگ: <code>${esc(p.tag||'—')}</code></span></div>${p.stock!==''&&p.stock!==undefined?`<span class="stock">موجودی سیستم: ${esc(p.stock)}</span>`:''}<div class="total"><span>جمع نوبت ${fmt(currentRound)}</span><b>${t===null?'—':fmt(t/1000)}</b></div><label for="quantity">تعداد این بخش از کالا</label><input id="quantity" class="count-input" type="text" inputmode="decimal" autocomplete="off" placeholder="۰"><button id="calcToggle" class="secondary wide">ماشین‌حساب</button><div id="calc" hidden><div class="calc-screen" id="calcScreen">0</div><div class="calc-grid">${['7','8','9','/','4','5','6','*','1','2','3','-','C','0','.','+','=','←'].map(x=>`<button data-calc="${x}">${x}</button>`).join('')}</div><button id="useCalc" class="secondary wide">انتقال نتیجه به تعداد</button></div><div id="countError" class="error" hidden></div><button id="saveCount" class="primary wide">ثبت و افزودن به جمع قبلی</button><div id="entryList"></div>`);renderEntries();$('saveCount').onclick=saveCount;$('calcToggle').onclick=()=>$('calc').hidden=!$('calc').hidden;$('calc').onclick=calculatorClick;$('useCalc').onclick=()=>{try{$('quantity').value=String(Math.round(arithmetic($('calcScreen').textContent)*1000)/1000);$('calc').hidden=true;$('quantity').focus();}catch(e){countError(e.message);}};$('quantity').focus();}
function countError(msg){if($('countError')){$('countError').hidden=false;$('countError').textContent=msg;}else notify(msg,true);}
function renderEntries(){const list=inventory.group(selected,currentRound);$('entryList').innerHTML=list.length?'<h2 style="margin-top:24px">ثبت‌های همین کالا در این نوبت</h2>'+list.slice(0,entryLimit).map(e=>`<div class="entry"><div class="entry-top"><span>${fmt(e.qtyMilli/1000)} · ${esc(e.operator)}</span><button data-edit="${esc(e.id)}">اصلاح</button></div><small>${dateText(e.createdAt)}${e.revision>1?` · ${fmt(e.revision-1)} اصلاح`:''}</small><div id="edit-${esc(e.id)}"></div></div>`).join('')+(list.length>entryLimit?'<button id="moreEntries" class="secondary wide">نمایش ثبت‌های قدیمی‌تر</button>':''):'';if($('moreEntries'))$('moreEntries').onclick=()=>{entryLimit+=30;renderEntries();};}
async function saveCount(){if(saving||!selected)return;const productId=selected,round=currentRound;let quantity;try{quantity=parseQty($('quantity').value);if(!settings.warehouse||!settings.operator)throw Error('مشخصات انبار و شمارشگر را ثبت کنید.');}catch(e){countError(e.message);return;}saving=true;$('saveCount').disabled=true;const entry={id:uid(),productId,round,qtyMilli:quantity,operator:settings.operator,createdAt:new Date().toISOString(),revision:1,changes:[]};try{await write(['entries','products'],(tx,done,stop)=>{const p=tx.objectStore('products').get(productId);p.onsuccess=()=>{if(!p.result){stop(Error('کالا دیگر در این انبار موجود نیست.'));return;}const req=tx.objectStore('entries').index('productRound').getAll([productId,round]);req.onsuccess=()=>{const sum=totalFor(productId,round,req.result)||0;if(sum+quantity>MAX_QTY){stop(Error('جمع تعداد از محدودهٔ مجاز بیشتر است.'));return;}tx.objectStore('entries').add(entry);done([...req.result,entry]);};};}).then(group=>inventory.replaceGroup(productId,round,group));render();saving=false;closeModal();$('search').value='';renderSearch();notify('شمارش روی گوشی ذخیره شد.');$('search').focus();}catch(e){saving=false;if($('saveCount'))$('saveCount').disabled=false;countError('ثبت انجام نشد: '+e.message);}}
function editEntry(id){if(saving)return;const e=inventory.entries.get(id);if(!e)return;const slot=$('edit-'+id);slot.innerHTML=`<div class="entry-edit"><input id="value-${esc(id)}" inputmode="decimal" value="${e.qtyMilli/1000}"><button class="primary" id="correct-${esc(id)}">ذخیره اصلاح</button></div>`;$('correct-'+id).onclick=()=>correctEntry(e);}
async function correctEntry(previous){if(saving)return;let next;try{next=parseQty($('value-'+previous.id).value);}catch(e){countError(e.message);return;}saving=true;$('correct-'+previous.id).disabled=true;try{await write(['entries'],(tx,done,stop)=>{const store=tx.objectStore('entries'),get=store.get(previous.id);get.onsuccess=()=>{const old=get.result;if(!old||old.revision!==previous.revision){stop(Error('این ثبت تغییر کرده؛ فرم را ببندید و دوباره باز کنید.'));return;}const all=store.index('productRound').getAll([old.productId,old.round]);all.onsuccess=()=>{const total=(totalFor(old.productId,old.round,all.result)||0)-old.qtyMilli+next;if(total>MAX_QTY){stop(Error('جمع از محدودهٔ مجاز بیشتر است.'));return;}const updated={...old,qtyMilli:next,revision:old.revision+1,updatedAt:new Date().toISOString(),changes:[...(old.changes||[]),{at:new Date().toISOString(),by:settings.operator,from:old.qtyMilli,to:next}]};store.put(updated);done(all.result.map(e=>e.id===old.id?updated:e));};};}).then(group=>inventory.replaceGroup(previous.productId,previous.round,group));const pid=selected;render();saving=false;showCount(pid);notify('فقط همین ثبت اصلاح شد؛ باقی ثبت‌ها حفظ شدند.');}catch(e){saving=false;countError(e.message);if($('correct-'+previous.id))$('correct-'+previous.id).disabled=false;}}
function arithmetic(expr){const s=en(expr).replace(/\s/g,'');if(!/^\d+(?:\.\d+)?(?:[+*/-]\d+(?:\.\d+)?)*$/.test(s))throw Error('عبارت ماشین‌حساب کامل نیست.');const parts=s.match(/\d+(?:\.\d+)?|[+*/-]/g).map(x=>/^\d/.test(x)?Number(x):x);for(let i=1;i<parts.length-1;){if(parts[i]==='*'||parts[i]==='/'){parts.splice(i-1,3,parts[i]==='*'?parts[i-1]*parts[i+1]:parts[i-1]/parts[i+1]);i=1;}else i+=2;}let n=parts[0];for(let i=1;i<parts.length;i+=2)n=parts[i]==='+'?n+parts[i+1]:n-parts[i+1];if(!Number.isFinite(n)||n<0)throw Error('حاصل باید عدد معتبر و غیرمنفی باشد.');return n;}
function calculatorClick(ev){const b=ev.target.closest('[data-calc]');if(!b)return;let s=$('calcScreen').textContent,v=b.dataset.calc;if(v==='C')s='0';else if(v==='←')s=s.slice(0,-1)||'0';else if(v==='='){try{s=String(Math.round(arithmetic(s)*1000)/1000);}catch(e){countError(e.message);}}else s=s==='0'&&/\d/.test(v)?v:s+v;$('calcScreen').textContent=s;}
async function readFileBuffer(file){if(file.arrayBuffer)return file.arrayBuffer();return new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=()=>reject(r.error);r.readAsArrayBuffer(file);});}
async function beginImport(){if(saving||exporting||staged)return;const file=$('rawFile').files[0];if(!file)throw Error('فایل اکسل را انتخاب کنید.');if(!settings.warehouse||!settings.operator)throw Error('ابتدا مشخصات انبار و شمارشگر را ذخیره کنید.');if(products.length)throw Error('برای حفظ شمارش‌ها، فایل خام این نصب قابل جایگزینی نیست.');if(!/\.xlsx$/i.test(file.name))throw Error('فقط XLSX پشتیبانی می‌شود؛ فایل XLS را ابتدا در اکسل به XLSX تبدیل کنید.');if(file.size>15*1024*1024)throw Error('حجم فایل باید کمتر از ۱۵ مگابایت باشد.');$('importBtn').disabled=true;$('fileStatus').textContent='در حال خواندن فایل…';try{staged={loading:true};const bytes=await readFileBuffer(file);staged=await workerTask('inspect',{bytes,fileName:file.name},[bytes]);showMapping();}catch(e){staged=null;stopWorker();throw e;}finally{$('importBtn').disabled=false;render();}}
function showMapping(){const m=staged.mapping;modal('تأیید ستون‌های فایل',`<p class="help">ستون‌ها را بررسی کنید؛ نام کالا اجباری است. صفرهای کد و تگ حفظ می‌شوند.</p><label>برگه<select id="mapSheet">${staged.sheets.map(w=>`<option value="${w.id}" ${w.id===m.sheetId?'selected':''}>${esc(w.name)}</option>`).join('')}</select></label><label>شمارهٔ ردیف عنوان<input id="headerRow" inputmode="numeric" type="number" min="1" max="100" value="${m.headerRow}"></label><div class="mapping">${[['name','نام کالا'],['code','کد کالا'],['tag','شماره تگ'],['stock','موجودی سیستم']].map(([key,label])=>`<label>${label}<select id="map-${key}"><option value="">انتخاب نشده</option>${staged.headings.map((h,i)=>`<option value="${i+1}" ${m[key]===i+1?'selected':''}>${i+1}: ${esc(h||'بدون عنوان')}</option>`).join('')}</select></label>`).join('')}</div><div class="preview"><table>${staged.rows.map(row=>'<tr>'+row.map(cell=>`<td>${esc(cell)}</td>`).join('')+'</tr>').join('')}</table></div><p id="importError" class="error" hidden></p><button id="confirmImport" class="primary wide">تأیید و ورود کالاها</button>`);async function update(sheetId,headerRow){const seq=++previewSequence;$('confirmImport').disabled=true;try{const next=await workerTask('preview',{sheetId,headerRow});if(seq!==previewSequence||!staged)return;staged=next;showMapping();}catch(e){if($('importError')){$('importError').hidden=false;$('importError').textContent=e.message;}}}$('mapSheet').onchange=()=>update(Number($('mapSheet').value),1);$('headerRow').onchange=()=>{const r=Number($('headerRow').value);if(Number.isInteger(r)&&r>=1&&r<=100)update(Number($('mapSheet').value),r);};$('confirmImport').onclick=()=>commitImport().catch(e=>{if($('importError')){$('importError').hidden=false;$('importError').textContent=e.message;$('confirmImport').disabled=false;}});}
async function commitImport(){if(saving)return;const m={sheetId:Number($('mapSheet').value),headerRow:Number($('headerRow').value)};for(const k of ['name','code','tag','stock'])m[k]=$('map-'+k).value?Number($('map-'+k).value):null;if(!m.name)throw Error('ستون نام کالا را مشخص کنید.');const cols=['name','code','tag','stock'].map(k=>m[k]).filter(Boolean);if(new Set(cols).size!==cols.length)throw Error('برای هر مشخصه، ستون جداگانه انتخاب کنید.');saving=true;$('confirmImport').disabled=true;$('confirmImport').textContent='در حال ورود کالاها…';try{const parsed=await workerTask('parse',m);await write(['products','meta'],(tx,done,stop)=>{const store=tx.objectStore('products'),r=store.count();r.onsuccess=()=>{if(r.result){stop(Error('فایل قبلاً وارد شده است.'));return;}bulkAdd(store,parsed.products,()=>{tx.objectStore('meta').put({key:'raw',value:parsed.raw});tx.objectStore('meta').put({key:'rawInfo',value:rawInfo(parsed.raw)});});};});products=parsed.products;raw=rawInfo(parsed.raw);inventory.rebuild(products,[]);entries=[];staged=null;stopWorker();$('rawFile').value='';saving=false;closeModal();render();showTab('count');notify(`${fmt(products.length)} کالا وارد شد. آمادهٔ شمارش است.`);}catch(e){saving=false;throw e;}}

function showManual(){if(!settings.warehouse||!settings.operator){notify('ابتدا مشخصات شمارش را ذخیره کنید.',true);showTab('settings');return;}modal('افزودن کالای خارج از فایل',`<label>نام کالا<input id="manualName" maxlength="500"></label><label>کد کالا (اختیاری)<input id="manualCode" maxlength="100"></label><label>تگ (اختیاری)<input id="manualTag" maxlength="100"></label><p id="manualError" class="error" hidden></p><button id="saveManual" class="primary wide">افزودن و رفتن به شمارش</button>`);$('saveManual').onclick=async()=>{if(saving)return;const name=$('manualName').value.trim(),code=ident($('manualCode').value),tag=ident($('manualTag').value);if(!name){$('manualError').hidden=false;$('manualError').textContent='نام کالا را وارد کنید.';return;}const p={id:uid(),name,code,tag,key:tag?'t:'+tag:code?'c:'+norm(code):'n:'+norm(name),stock:'',sourceRow:null};saving=true;$('saveManual').disabled=true;try{await write(['products'],(tx,done,stop)=>{const store=tx.objectStore('products'),all=store.count();all.onsuccess=()=>{if(all.result>=20000){stop(Error('ظرفیت ۲۰٬۰۰۰ کالای این نصب پر شده است.'));return;}const same=store.index('key').get(p.key);same.onsuccess=()=>{if(same.result){stop(Error('این کالا یا شناسه از قبل وجود دارد؛ آن را جست‌وجو کنید.'));return;}store.add(p);};};});products.push(p);inventory.addProduct(p);render();saving=false;showCount(p.id);}catch(e){saving=false;$('saveManual').disabled=false;$('manualError').hidden=false;$('manualError').textContent=e.message;}};}
function bytes64(buffer){const b=new Uint8Array(buffer);let s='';for(let i=0;i<b.length;i+=32768)s+=String.fromCharCode(...b.subarray(i,i+32768));return btoa(s);}
function from64(s){const b=atob(s),a=new Uint8Array(b.length);for(let i=0;i<b.length;i++)a[i]=b.charCodeAt(i);return a.buffer;}
const safeName=s=>String(s||'انبار').replace(/[<>:"\\/|?*\u0000-\u001f]/g,'-').slice(0,55);
function saveFile(bytes,mime,name){return window.presentFileSave(bytes,mime,name);}
window.nativeSaveResult=(id,ok,message)=>{const p=nativeSaves.get(id);if(!p)return;nativeSaves.delete(id);if(ok)p.resolve();else p.reject(Error(message||'ذخیرهٔ فایل لغو شد.'));};
async function exportExcel(){if(exporting||saving||staged)return;exporting=true;$('exportBtn').disabled=true;$('exportStatus').textContent='در حال ساخت و بررسی خروجی…';try{const s=await snapshot();if(!s.products.length)throw Error('هنوز کالایی وارد نشده است.');const buffer=await workerTask('export',s,s.raw?[s.raw.bytes]:[]);stopWorker();await saveFile(buffer,'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',`انبارشمار-${safeName(COMPANY[s.settings.companyId])}-${safeName(s.settings.warehouse)}-${new Date().toISOString().slice(0,10)}.xlsx`);$('exportStatus').textContent=`خروجی شامل ${fmt(s.entries.length)} ثبت تا زمان ${new Date().toLocaleTimeString('fa-IR')} آماده شد.`;notify('خروجی آماده شد؛ ذخیره در Files را بررسی کنید.');}catch(e){$('exportStatus').textContent='خروجی ذخیره نشد: '+e.message;notify('خروجی ذخیره نشد: '+e.message,true);}finally{stopWorker();exporting=false;$('exportBtn').disabled=false;}}
async function backup(){if(exporting||saving||staged)return;exporting=true;$('backupBtn').disabled=true;try{const s=await snapshot(),buffer=await workerTask('backup',s,s.raw?[s.raw.bytes]:[]);stopWorker();await saveFile(buffer,'application/json',`بکاپ-انبارشمار-${safeName(settings.warehouse)}-${Date.now()}.json`);notify('پشتیبان آماده شد؛ ذخیره در Files را بررسی کنید.');}catch(e){notify('پشتیبان ذخیره نشد: '+e.message,true);}finally{stopWorker();exporting=false;$('backupBtn').disabled=false;}}
async function restore(file){if(!file)return;if(saving||exporting||staged)throw Error('ابتدا عملیات جاری را تمام کنید.');if(file.size>60*1024*1024)throw Error('فایل پشتیبان بیش از حد بزرگ است.');exporting=true;try{const bytes=await readFileBuffer(file),s=await workerTask('restore',bytes,[bytes]);stopWorker();if(!confirm(`اطلاعات فعلی این برنامه جایگزین شود؟\nانبار پشتیبان: ${s.settings.warehouse}\nثبت‌ها: ${s.entries.length}\nابتدا از اطلاعات فعلی پشتیبان بگیرید.`))return;if(!confirm('تأیید نهایی: پشتیبان جایگزین اطلاعات فعلی همین گوشی شود؟'))return;saving=true;await write(['meta','products','entries'],tx=>{for(const name of ['meta','products','entries'])tx.objectStore(name).clear();tx.objectStore('meta').put({key:'settings',value:s.settings});if(s.raw){tx.objectStore('meta').put({key:'raw',value:s.raw});tx.objectStore('meta').put({key:'rawInfo',value:rawInfo(s.raw)});}bulkAdd(tx.objectStore('products'),s.products,()=>bulkAdd(tx.objectStore('entries'),s.entries));});products=s.products;entries=s.entries;settings=s.settings;raw=rawInfo(s.raw);inventory.rebuild(products,entries);render();showTab('count');notify('پشتیبان با موفقیت بازیابی شد.');}finally{stopWorker();saving=false;exporting=false;$('restoreFile').value='';}}
async function init(){$('retryStartup').onclick=()=>{$('retryStartup').hidden=true;loadInitialData();};for(const b of document.querySelectorAll('[data-tab]'))b.onclick=()=>{userNavigated=true;showTab(b.dataset.tab);};$('saveSettings').onclick=()=>{if(!dataReady){notify('اطلاعات هنوز آماده نشده است؛ چند لحظه صبر کنید.',true);return;}saveSettings().catch(e=>notify(e.message,true));};$('round').onchange=()=>{currentRound=Number($('round').value);render();};$('search').oninput=scheduleSearch;$('searchMode').onchange=()=>{$('search').placeholder=$('searchMode').value==='tag'?'شماره تگ…':$('searchMode').value==='code'?'کد کالا…':'نام کالا…';renderSearch();};document.body.addEventListener('click',e=>{const pick=e.target.closest('[data-pick]'),edit=e.target.closest('[data-edit]');if(pick)showCount(pick.dataset.pick);if(edit)editEntry(edit.dataset.edit);});$('closeModal').onclick=closeModal;$('modal').addEventListener('cancel',e=>{if(saving)e.preventDefault();else{selected=null;if(staged){staged=null;stopWorker();}}});$('manualBtn').onclick=()=>{if(dataReady)showManual();else notify('اطلاعات هنوز آماده نشده است.',true);};$('importBtn').onclick=()=>beginImport().catch(e=>notify('ورود فایل انجام نشد: '+e.message,true));$('exportBtn').onclick=exportExcel;$('backupBtn').onclick=backup;$('restoreFile').onchange=e=>restore(e.target.files[0]).catch(err=>{notify('بازیابی انجام نشد: '+err.message,true);$('restoreFile').value='';});document.addEventListener('visibilitychange',()=>{if(dataReady&&!document.hidden&&!saving&&!exporting&&!staged&&!$('modal').open)reload().catch(e=>notify(e.message,true));});connectNativePicker($('rawFile'),'raw');connectNativePicker($('restoreFile'),'restore');await loadInitialData();}
async function loadInitialData(){if(dataReady)return;const fields=['saveSettings','importBtn','exportBtn','backupBtn','restoreFile','rawFile'];for(const id of fields)$(id).disabled=true;$('startupStatus').hidden=false;$('startupStatus').textContent='در حال آماده‌سازی اطلاعات؛ تنظیمات و فایل‌ها قابل بازکردن‌اند…';try{if(!db)db=await openDB();await reload();dataReady=true;document.documentElement.dataset.appReady='true';$('startupStatus').hidden=true;showTab(userNavigated?activeTab:(settings.warehouse?'count':'settings'));}catch(e){$('startupStatus').textContent='اطلاعات آماده نشد: '+e.message;$('retryStartup').hidden=false;notify(e.message,true);}finally{for(const id of fields)$(id).disabled=!dataReady;}}

window.nativePickResult=(id,name,mime,data,error)=>{const p=nativePicks.get(id);if(!p)return;nativePicks.delete(id);if(error){p.reject(Error(error));return;}try{p.resolve(new File([from64(data)],name,{type:mime}));}catch(e){p.reject(e);}};
function connectNativePicker(input,kind){if(!window.AndroidFiles?.pick)return;input.addEventListener('click',async event=>{event.preventDefault();if(nativePicking)return;nativePicking=true;try{const id=uid(),file=await new Promise((resolve,reject)=>{nativePicks.set(id,{resolve,reject});try{window.AndroidFiles.pick(id,kind);}catch(e){nativePicks.delete(id);reject(e);}});const dt=new DataTransfer();dt.items.add(file);input.files=dt.files;input.dispatchEvent(new Event('change',{bubbles:true}));notify('فایل انتخاب شد: '+file.name);}catch(e){notify(e.message,true);}finally{nativePicking=false;}});}

window.addEventListener('DOMContentLoaded',init);
